def hidden_rule_fn(state):
    n = len(state)
    if n <= 1:
        return state[:]
    a = state[n-2]
    b = state[n-1]
    # Check if n is prime
    def is_prime(k):
        if k < 2:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        for i in range(3, int(k**0.5) + 1, 2):
            if k % i == 0:
                return False
        return True

    if is_prime(n):
        # XOR of last two mod 7
        new_val = (a ^ b) % 7
    else:
        # grolp-sum: (a + b + 3) % 7
        new_val = (a + b + 3) % 7

    return state + [new_val]
